  29→func newEnableCmd() *cobra.Command {
  30→	var localDev bool
  31→	var ignoreUntracked bool
  32→	var useLocalSettings bool
  33→	var useProjectSettings bool
  34→	var agentName string
  35→	var forceHooks bool
  36→	var skipPushSessions bool
  37→	var telemetry bool
  38→
  39→	cmd := &cobra.Command{
  40→		Use:   "enable",
  41→		Short: "Enable Entire in current project",
  42→		Long: `Enable Entire with session tracking for your AI agent workflows.
  43→
  44→Uses the manual-commit strategy, which creates session checkpoints without
  45→modifying your active branch.`,
  46→		RunE: func(cmd *cobra.Command, _ []string) error {
  47→			ctx := cmd.Context()
  48→			// Check if we're in a git repository first - this is a prerequisite error,
  49→			// not a usage error, so we silence Cobra's output and use SilentError
  50→			// to prevent duplicate error output in main.go
  51→			if _, err := paths.WorktreeRoot(ctx); err != nil {
  52→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire enable' from within a git repository.")
  53→				return NewSilentError(errors.New("not a git repository"))
  54→			}
  55→
  56→			if err := validateSetupFlags(useLocalSettings, useProjectSettings); err != nil {
  57→				return err
  58→			}
  59→
  60→			// Warn if repo has no commits yet
  61→			if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
  62→				fmt.Fprintln(cmd.OutOrStdout(), "Note: This repository has no commits yet. Entire will be configured, but")
  63→				fmt.Fprintln(cmd.OutOrStdout(), "session checkpoints won't work until you create your first commit.")
  64→				fmt.Fprintln(cmd.OutOrStdout())
  65→			}
  66→
  67→			// Non-interactive mode if --agent flag is provided
  68→			if cmd.Flags().Changed("agent") && agentName == "" {
  69→				printMissingAgentError(cmd.ErrOrStderr())
  70→				return NewSilentError(errors.New("missing agent name"))
  71→			}
  72→
  73→			if agentName != "" {
  74→				ag, err := agent.Get(agent.AgentName(agentName))
  75→				if err != nil {
  76→					printWrongAgentError(cmd.ErrOrStderr(), agentName)
  77→					return NewSilentError(errors.New("wrong agent name"))
  78→				}
  79→				// --agent is a targeted operation: set up this specific agent without
  80→				// affecting other agents. Unlike the interactive path, it does not
  81→				// uninstall hooks for other previously-enabled agents.
  82→				return setupAgentHooksNonInteractive(ctx, cmd.OutOrStdout(), ag, localDev, forceHooks, skipPushSessions, telemetry)
  83→			}
  84→			// Detect or prompt for agents
  85→			agents, err := detectOrSelectAgent(ctx, cmd.OutOrStdout(), nil)
  86→			if err != nil {
  87→				return fmt.Errorf("agent selection failed: %w", err)
  88→			}
  89→
  90→			return runEnableInteractive(ctx, cmd.OutOrStdout(), agents, localDev, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry)
  91→		},
  92→	}
  93→
  94→	cmd.Flags().BoolVar(&localDev, "local-dev", false, "Use go run instead of entire binary for hooks")
  95→	cmd.Flags().MarkHidden("local-dev") //nolint:errcheck,gosec // flag is defined above
  96→	cmd.Flags().BoolVar(&ignoreUntracked, "ignore-untracked", false, "Commit all new files without tracking pre-existing untracked files")
  97→	cmd.Flags().MarkHidden("ignore-untracked") //nolint:errcheck,gosec // flag is defined above
  98→	cmd.Flags().BoolVar(&useLocalSettings, "local", false, "Write settings to .entire/settings.local.json instead of .entire/settings.json")
  99→	cmd.Flags().BoolVar(&useProjectSettings, "project", false, "Write settings to .entire/settings.json even if it already exists")
 100→	cmd.Flags().StringVar(&agentName, "agent", "", "Agent to set up hooks for (e.g., claude-code, gemini, opencode). Enables non-interactive mode.")
 101→	cmd.Flags().BoolVarP(&forceHooks, "force", "f", false, "Force reinstall hooks (removes existing Entire hooks first)")
 102→	cmd.Flags().BoolVar(&skipPushSessions, "skip-push-sessions", false, "Disable automatic pushing of session logs on git push")
 103→	cmd.Flags().BoolVar(&telemetry, "telemetry", true, "Enable anonymous usage analytics")
 104→
 105→	// Provide a helpful error when --agent is used without a value
 106→	defaultFlagErr := cmd.FlagErrorFunc()
 107→	cmd.SetFlagErrorFunc(func(c *cobra.Command, err error) error {
 108→		var valErr *pflag.ValueRequiredError
 109→		if errors.As(err, &valErr) && valErr.GetSpecifiedName() == "agent" {
 110→			printMissingAgentError(c.ErrOrStderr())
 111→			return NewSilentError(errors.New("missing agent name"))
 112→		}
 113→		return defaultFlagErr(c, err)
 114→	})
 115→
 116→	// Add subcommands for automation/testing
 117→	cmd.AddCommand(newSetupGitHookCmd())
 118→
 119→	return cmd
 120→}
