 157→// runEnableInteractive runs the interactive enable flow.
 158→// agents must be provided by the caller (via detectOrSelectAgent).
 159→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, localDev, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry bool) error {
 160→	// Uninstall hooks for agents that were previously active but are no longer selected
 161→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 162→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 163→	}
 164→
 165→	// Setup agent hooks for all selected agents
 166→	for _, ag := range agents {
 167→		if _, err := setupAgentHooks(ctx, ag, localDev, forceHooks); err != nil {
 168→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 169→		}
 170→	}
 171→
 172→	// Setup .entire directory
 173→	if _, err := setupEntireDirectory(ctx); err != nil {
 174→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 175→	}
 176→
 177→	// Load existing settings to preserve other options (like strategy_options.push)
 178→	settings, err := LoadEntireSettings(ctx)
 179→	if err != nil {
 180→		// If we can't load, start with defaults
 181→		settings = &EntireSettings{}
 182→	}
 183→	// Update the specific fields
 184→	settings.LocalDev = localDev
 185→	settings.Enabled = true
 186→
 187→	// Set push_sessions option if --skip-push-sessions flag was provided
 188→	if skipPushSessions {
 189→		if settings.StrategyOptions == nil {
 190→			settings.StrategyOptions = make(map[string]interface{})
 191→		}
 192→		settings.StrategyOptions["push_sessions"] = false
 193→	}
 194→
 195→	// Determine which settings file to write to
 196→	// First run always creates settings.json (no prompt)
 197→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 198→	if err != nil {
 199→		entireDirAbs = paths.EntireDir // Fallback to relative
 200→	}
 201→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
 202→
 203→	if showNotification {
 204→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 205→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 206→	}
 207→
 208→	// Helper to save settings to the appropriate file
 209→	saveSettings := func() error {
 210→		if shouldUseLocal {
 211→			return SaveEntireSettingsLocal(ctx, settings)
 212→		}
 213→		return SaveEntireSettings(ctx, settings)
 214→	}
 215→
 216→	// Save settings before telemetry prompt so config is persisted even if the user cancels
 217→	if err := saveSettings(); err != nil {
 218→		return fmt.Errorf("failed to save settings: %w", err)
 219→	}
 220→
 221→	if _, err := strategy.InstallGitHook(ctx, true, localDev); err != nil {
 222→		return fmt.Errorf("failed to install git hooks: %w", err)
 223→	}
 224→	strategy.CheckAndWarnHookManagers(ctx, w, localDev)
 225→	fmt.Fprintln(w, "✓ Hooks installed")
 226→
 227→	configDisplay := configDisplayProject
 228→	if shouldUseLocal {
 229→		configDisplay = configDisplayLocal
 230→	}
 231→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 232→
 233→	// Ask about telemetry consent (only if not already asked)
 234→	fmt.Fprintln(w)
 235→	if err := promptTelemetryConsent(settings, telemetry); err != nil {
 236→		return fmt.Errorf("telemetry consent: %w", err)
 237→	}
 238→	// Save again to persist telemetry choice
 239→	if err := saveSettings(); err != nil {
 240→		return fmt.Errorf("failed to save settings: %w", err)
 241→	}
 242→
 243→	if err := strategy.EnsureSetup(ctx); err != nil {
 244→		return fmt.Errorf("failed to setup strategy: %w", err)
 245→	}
 246→
 247→	fmt.Fprintln(w, "\nReady.")
 248→
 249→	return nil
 250→}
