 252→// runEnable is a simple enable that just sets the enabled flag (for programmatic use).
 253→func runEnable(ctx context.Context, w io.Writer) error {
 254→	settings, err := LoadEntireSettings(ctx)
 255→	if err != nil {
 256→		return fmt.Errorf("failed to load settings: %w", err)
 257→	}
 258→
 259→	settings.Enabled = true
 260→	if err := SaveEntireSettings(ctx, settings); err != nil {
 261→		return fmt.Errorf("failed to save settings: %w", err)
 262→	}
 263→
 264→	fmt.Fprintln(w, "Entire is now enabled.")
 265→	return nil
 266→}
