 268→func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
 269→	settings, err := LoadEntireSettings(ctx)
 270→	if err != nil {
 271→		return fmt.Errorf("failed to load settings: %w", err)
 272→	}
 273→
 274→	settings.Enabled = false
 275→
 276→	// If --project flag is specified, always write to project settings
 277→	if useProjectSettings {
 278→		if err := SaveEntireSettings(ctx, settings); err != nil {
 279→			return fmt.Errorf("failed to save settings: %w", err)
 280→		}
 281→	} else {
 282→		// Always write to local settings file (create if doesn't exist)
 283→		if err := SaveEntireSettingsLocal(ctx, settings); err != nil {
 284→			return fmt.Errorf("failed to save local settings: %w", err)
 285→		}
 286→	}
 287→
 288→	fmt.Fprintln(w, "Entire is now disabled.")
 289→	return nil
 290→}
