 295→// checkDisabledGuard checks if Entire is disabled and prints a message if so.
 296→// Returns true if the caller should exit (i.e., Entire is disabled).
 297→// On error reading settings, defaults to enabled (returns false).
 298→func checkDisabledGuard(w io.Writer) bool {
 299→	enabled, err := IsEnabled(context.Background())
