 311→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 312→// installed but are not in the selected list. This handles the case where a user
 313→// re-runs `entire enable` and deselects an agent.
 314→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 315→	installedNames := GetAgentsWithHooksInstalled(ctx)
 316→	if len(installedNames) == 0 {
 317→		return nil
 318→	}
 319→
 320→	selectedSet := make(map[agent.AgentName]struct{}, len(selectedAgents))
 321→	for _, ag := range selectedAgents {
 322→		selectedSet[ag.Name()] = struct{}{}
 323→	}
 324→
 325→	var errs []error
 326→	for _, name := range installedNames {
 327→		if _, selected := selectedSet[name]; selected {
 328→			continue
 329→		}
 330→		ag, err := agent.Get(name)
 331→		if err != nil {
 332→			continue
 333→		}
 334→		hookAgent, ok := ag.(agent.HookSupport)
 335→		if !ok {
 336→			continue
 337→		}
 338→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 339→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 340→		} else {
 341→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 342→		}
 343→	}
 344→	return errors.Join(errs...)
 345→}
