 347→// setupAgentHooks sets up hooks for a given agent.
 348→// Returns the number of hooks installed (0 if already installed).
 349→func setupAgentHooks(ctx context.Context, ag agent.Agent, localDev, forceHooks bool) (int, error) {
 350→	hookAgent, ok := ag.(agent.HookSupport)
 351→	if !ok {
 352→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 353→	}
 354→
 355→	count, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 356→	if err != nil {
 357→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 358→	}
 359→
 360→	return count, nil
 361→}
 362→
 363→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 364→// Returns the detected/selected agents and any error.
 365→//
 366→// On first run (no hooks installed):
 367→//   - Single detected agent: used automatically
 368→//   - Multiple/no detected agents: interactive multi-select prompt
 369→//
 370→// On re-run (hooks already installed):
 371→//   - Always shows the interactive multi-select
 372→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 373→//
 374→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 375→// It receives available agent names and returns the selected names.
 376→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 377→	// Check for agents with hooks already installed (re-run detection)
 378→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 379→	hasInstalledHooks := len(installedAgentNames) > 0
 380→
 381→	// Try auto-detection
 382→	detected := agent.DetectAll(ctx)
 383→
 384→	// First run: use existing auto-detect shortcuts
 385→	if !hasInstalledHooks {
 386→		switch {
 387→		case len(detected) == 1:
 388→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 389→			return detected, nil
 390→
 391→		case len(detected) > 1:
 392→			agentTypes := make([]string, 0, len(detected))
 393→			for _, ag := range detected {
 394→				agentTypes = append(agentTypes, string(ag.Type()))
 395→			}
 396→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 397→			fmt.Fprintln(w)
 398→		}
 399→	}
 400→
 401→	// Check if we can prompt interactively
 402→	if !canPromptInteractively() {
 403→		if hasInstalledHooks {
 404→			// Re-run without TTY — keep currently installed agents
 405→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 406→			for _, name := range installedAgentNames {
 407→				ag, err := agent.Get(name)
 408→				if err != nil {
 409→					continue
 410→				}
 411→				agents = append(agents, ag)
 412→			}
 413→			return agents, nil
 414→		}
 415→		if len(detected) > 0 {
 416→			return detected, nil
 417→		}
 418→		defaultAgent := agent.Default()
 419→		if defaultAgent == nil {
 420→			return nil, errors.New("no default agent available")
 421→		}
 422→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 423→		return []agent.Agent{defaultAgent}, nil
 424→	}
 425→
 426→	if !hasInstalledHooks && len(detected) == 0 {
 427→		fmt.Fprintln(w, "No agent configuration detected (e.g., .claude, .gemini, or .opencode directory).")
 428→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 429→		fmt.Fprintln(w)
 430→	}
 431→
 432→	// Build pre-selection set.
 433→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 434→	// On first run: pre-select all detected agents.
 435→	preSelectedSet := make(map[agent.AgentName]struct{})
 436→	if hasInstalledHooks {
 437→		for _, name := range installedAgentNames {
 438→			preSelectedSet[name] = struct{}{}
 439→		}
 440→	} else {
 441→		for _, ag := range detected {
 442→			preSelectedSet[ag.Name()] = struct{}{}
 443→		}
 444→	}
 445→
 446→	// Build options from registered agents
 447→	agentNames := agent.List()
 448→	options := make([]huh.Option[string], 0, len(agentNames))
 449→	for _, name := range agentNames {
 450→		ag, err := agent.Get(name)
 451→		if err != nil {
 452→			continue
 453→		}
 454→		// Only show agents that support hooks
 455→		if _, ok := ag.(agent.HookSupport); !ok {
 456→			continue
 457→		}
 458→		opt := huh.NewOption(string(ag.Type()), string(name))
 459→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 460→			opt = opt.Selected(true)
 461→		}
 462→		options = append(options, opt)
 463→	}
 464→
 465→	if len(options) == 0 {
 466→		return nil, errors.New("no agents with hook support available")
 467→	}
 468→
 469→	// Collect available agent names for the selector
 470→	availableNames := make([]string, 0, len(options))
 471→	for _, opt := range options {
 472→		availableNames = append(availableNames, opt.Value)
 473→	}
 474→
 475→	var selectedAgentNames []string
 476→	if selectFn != nil {
 477→		var err error
 478→		selectedAgentNames, err = selectFn(availableNames)
 479→		if err != nil {
 480→			return nil, err
 481→		}
 482→		if len(selectedAgentNames) == 0 {
 483→			return nil, errors.New("no agents selected")
 484→		}
 485→	} else {
 486→		form := NewAccessibleForm(
 487→			huh.NewGroup(
 488→				huh.NewMultiSelect[string]().
 489→					Title("Which agents are you using?").
 490→					Description("Use space to select, enter to confirm.").
 491→					Options(options...).
 492→					Validate(func(selected []string) error {
 493→						if len(selected) == 0 {
 494→							return errors.New("please select at least one agent")
 495→						}
 496→						return nil
 497→					}).
 498→					Value(&selectedAgentNames),
 499→			),
 500→		)
 501→		if err := form.Run(); err != nil {
 502→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 503→		}
 504→	}
 505→
 506→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 507→	for _, name := range selectedAgentNames {
 508→		selectedAgent, err := agent.Get(agent.AgentName(name))
 509→		if err != nil {
 510→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 511→		}
 512→		selectedAgents = append(selectedAgents, selectedAgent)
 513→	}
 514→
 515→	agentTypes := make([]string, 0, len(selectedAgents))
 516→	for _, ag := range selectedAgents {
 517→		agentTypes = append(agentTypes, string(ag.Type()))
 518→	}
 519→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 520→	return selectedAgents, nil
 521→}
