 523→// canPromptInteractively checks if we can show interactive prompts.
 524→// Returns false when running in CI, tests, or other non-interactive environments.
 525→func canPromptInteractively() bool {
 526→	// Check for test environment
 527→	if os.Getenv("ENTIRE_TEST_TTY") != "" {
 528→		return os.Getenv("ENTIRE_TEST_TTY") == "1"
 529→	}
 530→
 531→	// Check if /dev/tty is available
 532→	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
 533→	if err != nil {
 534→		return false
 535→	}
 536→	_ = tty.Close()
 537→	return true
 538→}
