 565→
 566→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 567→// If strategyName is provided, it sets the strategy; otherwise uses default.
 568→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, localDev, forceHooks, skipPushSessions, telemetry bool) error {
 569→	agentName := ag.Name()
 570→	// Check if agent supports hooks
 571→	hookAgent, ok := ag.(agent.HookSupport)
 572→	if !ok {
 573→		return fmt.Errorf("agent %s does not support hooks", agentName)
 574→	}
 575→
 576→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 577→
 578→	// Install agent hooks (agent hooks don't depend on settings)
 579→	installedHooks, err := hookAgent.InstallHooks(ctx, localDev, forceHooks)
 580→	if err != nil {
 581→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 582→	}
 583→
 584→	// Setup .entire directory
 585→	if _, err := setupEntireDirectory(ctx); err != nil {
 586→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 587→	}
 588→
 589→	// Load existing settings to preserve other options (like strategy_options.push)
 590→	settings, err := LoadEntireSettings(ctx)
 591→	if err != nil {
 592→		// If we can't load, start with defaults
 593→		settings = &EntireSettings{}
 594→	}
 595→	settings.Enabled = true
 596→	if localDev {
 597→		settings.LocalDev = localDev
 598→	}
 599→
 600→	// Set push_sessions option if --skip-push-sessions flag was provided
 601→	if skipPushSessions {
 602→		if settings.StrategyOptions == nil {
 603→			settings.StrategyOptions = make(map[string]interface{})
 604→		}
 605→		settings.StrategyOptions["push_sessions"] = false
 606→	}
 607→
 608→	// Handle telemetry for non-interactive mode
 609→	// Note: if telemetry is nil (not configured), it defaults to disabled
 610→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 611→		f := false
 612→		settings.Telemetry = &f
 613→	}
 614→
 615→	if err := SaveEntireSettings(ctx, settings); err != nil {
 616→		return fmt.Errorf("failed to save settings: %w", err)
 617→	}
 618→
 619→	if _, err := strategy.InstallGitHook(ctx, true, localDev); err != nil {
 620→		return fmt.Errorf("failed to install git hooks: %w", err)
 621→	}
 622→	strategy.CheckAndWarnHookManagers(ctx, w, localDev)
 623→
 624→	if installedHooks == 0 {
 625→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 626→		if ag.IsPreview() {
 627→			msg += " (Preview)"
 628→		}
 629→		fmt.Fprintf(w, "%s\n", msg)
 630→	} else {
 631→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 632→		if ag.IsPreview() {
 633→			msg += " (Preview)"
 634→		}
 635→		fmt.Fprintf(w, "%s\n", msg)
 636→	}
 637→
 638→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 639→
 640→	if err := strategy.EnsureSetup(ctx); err != nil {
 641→		return fmt.Errorf("failed to setup strategy: %w", err)
 642→	}
 643→
 644→	fmt.Fprintln(w, "\nReady.")
 645→
 646→	return nil
 647→}
