 657→// determineSettingsTarget decides whether to write to settings.local.json based on:
 658→// - Whether settings.json already exists
 659→// - The --local and --project flags
 660→// Returns (useLocal, showNotification).
 661→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
 662→	// Explicit --local flag always uses local settings
 663→	if useLocal {
 664→		return true, false
 665→	}
 666→
 667→	// Explicit --project flag always uses project settings
 668→	if useProject {
 669→		return false, false
 670→	}
 671→
 672→	// No flags specified - check if settings file exists
 673→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
 674→	if _, err := os.Stat(settingsPath); err == nil {
 675→		// Settings file exists - auto-redirect to local with notification
 676→		return true, true
 677→	}
 678→
 679→	// Settings file doesn't exist - create it
 680→	return false, false
 681→}
