 690→	}
 691→
 692→	// Check if directory already exists
 693→	created := false
 694→	if _, err := os.Stat(entireDirAbs); os.IsNotExist(err) {
 695→		created = true
 696→	}
 697→
 698→	// Create .entire directory
 699→	//nolint:gosec // G301: Project directory needs standard permissions for git
 700→	if err := os.MkdirAll(entireDirAbs, 0o755); err != nil {
