 752→// shellCompletionComment is the comment preceding the completion line
 753→const shellCompletionComment = "# Entire CLI shell completion"
 754→
 755→// errUnsupportedShell is returned when the user's shell is not supported for completion.
 756→var errUnsupportedShell = errors.New("unsupported shell")
 757→
 758→// shellCompletionTarget returns the rc file path and completion lines for the
 759→// user's current shell.
 760→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 761→	home, err := os.UserHomeDir()
 762→	if err != nil {
 763→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 764→	}
 765→
 766→	shell := os.Getenv("SHELL")
 767→	switch {
 768→	case strings.Contains(shell, "zsh"):
 769→		return "Zsh",
 770→			filepath.Join(home, ".zshrc"),
 771→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 772→			nil
 773→	case strings.Contains(shell, "bash"):
 774→		bashRC := filepath.Join(home, ".bashrc")
 775→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
 776→			bashRC = filepath.Join(home, ".bash_profile")
 777→		}
 778→		return "Bash",
 779→			bashRC,
 780→			"source <(entire completion bash)",
 781→			nil
 782→	case strings.Contains(shell, "fish"):
 783→		return "Fish",
 784→			filepath.Join(home, ".config", "fish", "config.fish"),
 785→			"entire completion fish | source",
 786→			nil
 787→	default:
 788→		return "", "", "", errUnsupportedShell
 789→	}
 790→}
 791→
 792→// promptShellCompletion offers to add shell completion to the user's rc file.
 793→// Only prompts if completion is not already configured.
 794→func promptShellCompletion(w io.Writer) error {
 795→	shellName, rcFile, completionLine, err := shellCompletionTarget()
 796→	if err != nil {
 797→		if errors.Is(err, errUnsupportedShell) {
 798→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
 799→			return nil
 800→		}
 801→		return fmt.Errorf("shell completion: %w", err)
 802→	}
 803→
 804→	if isCompletionConfigured(rcFile) {
 805→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
 806→		return nil
 807→	}
 808→
 809→	var selected string
 810→	form := NewAccessibleForm(
 811→		huh.NewGroup(
 812→			huh.NewSelect[string]().
 813→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
 814→				Options(
 815→					huh.NewOption("Yes", "yes"),
 816→					huh.NewOption("No", "no"),
 817→				).
 818→				Value(&selected),
 819→		),
 820→	)
 821→
 822→	if err := form.Run(); err != nil {
 823→		//nolint:nilerr // User cancelled - not a fatal error, just skip
 824→		return nil
 825→	}
 826→
 827→	if selected != "yes" {
 828→		return nil
 829→	}
 830→
 831→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
 832→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
 833→	}
 834→
 835→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
 836→	fmt.Fprintln(w, "  Restart your shell to activate")
 837→
 838→	return nil
 839→}
 840→
 841→// isCompletionConfigured checks if shell completion is already in the rc file.
 842→func isCompletionConfigured(rcFile string) bool {
 843→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 844→	content, err := os.ReadFile(rcFile)
 845→	if err != nil {
 846→		return false // File doesn't exist or can't read, treat as not configured
 847→	}
 848→	return strings.Contains(string(content), "entire completion")
 849→}
 850→
 851→// appendShellCompletion adds the completion line to the rc file.
 852→func appendShellCompletion(rcFile, completionLine string) error {
 853→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
 854→		return fmt.Errorf("creating directory: %w", err)
 855→	}
 856→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
 857→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
 858→	if err != nil {
 859→		return fmt.Errorf("opening file: %w", err)
 860→	}
 861→	defer f.Close()
 862→
 863→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
 864→	if err != nil {
 865→		return fmt.Errorf("writing completion: %w", err)
 866→	}
 867→	return nil
 868→}
