 913→// runUninstall completely removes Entire from the repository.
 914→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 915→	// Check if we're in a git repository
 916→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 917→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 918→		return NewSilentError(errors.New("not a git repository"))
 919→	}
 920→
 921→	// Gather counts for display
 922→	sessionStateCount := countSessionStates()
 923→	shadowBranchCount := countShadowBranches()
 924→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 925→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 926→	entireDirExists := checkEntireDirExists()
 927→
 928→	// Check if there's anything to uninstall
 929→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 930→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 931→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 932→		return nil
 933→	}
 934→
 935→	// Show confirmation prompt unless --force
 936→	if !force {
 937→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
 938→		if entireDirExists {
 939→			fmt.Fprintln(w, "  - .entire/ directory")
 940→		}
 941→		if gitHooksInstalled {
 942→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
 943→		}
 944→		if sessionStateCount > 0 {
 945→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
 946→		}
 947→		if shadowBranchCount > 0 {
 948→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
 949→		}
 950→		if len(agentsWithInstalledHooks) > 0 {
 951→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
 952→			for _, name := range agentsWithInstalledHooks {
 953→				if ag, err := agent.Get(name); err == nil {
 954→					displayNames = append(displayNames, string(ag.Type()))
 955→				}
 956→			}
 957→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
 958→		}
 959→		fmt.Fprintln(w)
 960→
 961→		var confirmed bool
 962→		form := NewAccessibleForm(
 963→			huh.NewGroup(
 964→				huh.NewConfirm().
 965→					Title("Are you sure you want to uninstall Entire?").
 966→					Affirmative("Yes, uninstall").
 967→					Negative("Cancel").
 968→					Value(&confirmed),
 969→			),
 970→		)
 971→
 972→		if err := form.Run(); err != nil {
 973→			return fmt.Errorf("confirmation cancelled: %w", err)
 974→		}
 975→
 976→		if !confirmed {
 977→			fmt.Fprintln(w, "Uninstall cancelled.")
 978→			return nil
 979→		}
 980→	}
 981→
 982→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
 983→
 984→	// 1. Remove agent hooks (lowest risk)
 985→	if err := removeAgentHooks(ctx, w); err != nil {
 986→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
 987→	}
 988→
 989→	// 2. Remove git hooks
 990→	removed, err := strategy.RemoveGitHook(ctx)
 991→	if err != nil {
 992→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
 993→	} else if removed > 0 {
 994→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
 995→	}
 996→
 997→	// 3. Remove session state files
 998→	statesRemoved, err := removeAllSessionStates()
 999→	if err != nil {
1000→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1001→	} else if statesRemoved > 0 {
1002→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1003→	}
1004→
1005→	// 4. Remove .entire/ directory
1006→	if err := removeEntireDirectory(); err != nil {
1007→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1008→	} else if entireDirExists {
1009→		fmt.Fprintln(w, "  Removed .entire directory")
1010→	}
1011→
1012→	// 5. Remove shadow branches
1013→	branchesRemoved, err := removeAllShadowBranches()
1014→	if err != nil {
1015→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1016→	} else if branchesRemoved > 0 {
1017→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1018→	}
1019→
1020→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1021→	return nil
1022→}
