1024→// countSessionStates returns the number of active session state files.
1025→func countSessionStates() int {
1026→	store, err := session.NewStateStore(context.Background())
1027→	if err != nil {
1028→		return 0
1029→	}
1030→	states, err := store.List(context.Background())
1031→	if err != nil {
1032→		return 0
1033→	}
1034→	return len(states)
1035→}
