1056→// removeAgentHooks removes hooks from all agents that support hooks.
1057→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1058→	var errs []error
1059→	for _, name := range agent.List() {
1060→		ag, err := agent.Get(name)
1061→		if err != nil {
1062→			continue
1063→		}
1064→		hs, ok := ag.(agent.HookSupport)
1065→		if !ok {
1066→			continue
1067→		}
1068→		wasInstalled := hs.AreHooksInstalled(ctx)
1069→		if err := hs.UninstallHooks(ctx); err != nil {
1070→			errs = append(errs, err)
1071→		} else if wasInstalled {
1072→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1073→		}
1074→	}
1075→	return errors.Join(errs...)
1076→}
