1078→// removeAllSessionStates removes all session state files and the directory.
1079→func removeAllSessionStates() (int, error) {
1080→	store, err := session.NewStateStore(context.Background())
1081→	if err != nil {
1082→		return 0, fmt.Errorf("failed to create state store: %w", err)
1083→	}
1084→
1085→	// Count states before removing
1086→	states, err := store.List(context.Background())
1087→	if err != nil {
1088→		return 0, fmt.Errorf("failed to list session states: %w", err)
1089→	}
1090→	count := len(states)
1091→
1092→	// Remove the entire directory
1093→	if err := store.RemoveAll(); err != nil {
1094→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1095→	}
1096→
1097→	return count, nil
1098→}
