 99→// runStatusDetailed shows the effective status plus detailed status for each settings file.
100→func runStatusDetailed(ctx context.Context, w io.Writer, sty statusStyles, settingsPath, localSettingsPath string, projectExists, localExists bool) error {
101→	// First show the effective/merged status
102→	effectiveSettings, err := LoadEntireSettings(ctx)
103→	if err != nil {
104→		return fmt.Errorf("failed to load settings: %w", err)
105→	}
106→	fmt.Fprintln(w)
107→	settings.WriteDeprecatedStrategyWarnings(ctx, w)
108→	fmt.Fprintln(w)
109→	fmt.Fprintln(w, formatSettingsStatusShort(effectiveSettings, sty))
110→	fmt.Fprintln(w) // blank line
111→
112→	// Show project settings if it exists
113→	if projectExists {
114→		projectSettings, err := settings.LoadFromFile(settingsPath)
115→		if err != nil {
116→			return fmt.Errorf("failed to load project settings: %w", err)
117→		}
118→		fmt.Fprintln(w, formatSettingsStatus("Project", projectSettings, sty))
119→	}
120→
121→	// Show local settings if it exists
122→	if localExists {
123→		localSettings, err := settings.LoadFromFile(localSettingsPath)
124→		if err != nil {
125→			return fmt.Errorf("failed to load local settings: %w", err)
126→		}
127→		fmt.Fprintln(w, formatSettingsStatus("Local", localSettings, sty))
128→	}
129→
130→	if effectiveSettings.Enabled {
131→		writeActiveSessions(w, sty)
132→	}
133→
134→	return nil
135→}
