190→// timeAgo formats a time as a human-readable relative duration.
191→func timeAgo(t time.Time) string {
192→	d := time.Since(t)
193→	switch {
194→	case d < time.Minute:
195→		return "just now"
196→	case d < time.Hour:
197→		m := int(d.Minutes())
198→		return fmt.Sprintf("%dm ago", m)
199→	case d < 24*time.Hour:
200→		h := int(d.Hours())
201→		return fmt.Sprintf("%dh ago", h)
202→	default:
203→		days := int(d.Hours() / 24)
204→		return fmt.Sprintf("%dd ago", days)
205→	}
206→}
