208→// worktreeGroup groups sessions by worktree path for display.
209→type worktreeGroup struct {
210→	path     string
211→	branch   string
212→	sessions []*session.State
213→}
214→
215→const (
216→	unknownPlaceholder  = "(unknown)"
217→	detachedHEADDisplay = "HEAD"
218→)
219→
220→// writeActiveSessions writes active session information grouped by worktree.
221→func writeActiveSessions(w io.Writer, sty statusStyles) {
222→	store, err := session.NewStateStore(context.Background())
223→	if err != nil {
224→		return
225→	}
226→
227→	states, err := store.List(context.Background())
228→	if err != nil || len(states) == 0 {
229→		return
230→	}
231→
232→	// Filter to active sessions only
233→	var active []*session.State
234→	for _, s := range states {
235→		if s.EndedAt == nil {
236→			active = append(active, s)
237→		}
238→	}
239→	if len(active) == 0 {
240→		return
241→	}
242→
243→	// Group by worktree path
244→	groups := make(map[string]*worktreeGroup)
245→	for _, s := range active {
246→		wp := s.WorktreePath
247→		if wp == "" {
248→			wp = unknownPlaceholder
249→		}
250→		g, ok := groups[wp]
251→		if !ok {
252→			g = &worktreeGroup{path: wp}
253→			groups[wp] = g
254→		}
255→		g.sessions = append(g.sessions, s)
256→	}
257→
258→	// Resolve branch names for each worktree (skip for unknown paths)
259→	for _, g := range groups {
260→		if g.path != unknownPlaceholder {
261→			g.branch = resolveWorktreeBranch(g.path)
262→		}
263→	}
264→
265→	// Sort groups: alphabetical by path
266→	sortedGroups := make([]*worktreeGroup, 0, len(groups))
267→	for _, g := range groups {
268→		sortedGroups = append(sortedGroups, g)
269→	}
270→	sort.Slice(sortedGroups, func(i, j int) bool {
271→		return sortedGroups[i].path < sortedGroups[j].path
272→	})
273→
274→	// Sort sessions within each group by StartedAt (newest first)
275→	for _, g := range sortedGroups {
276→		sort.Slice(g.sessions, func(i, j int) bool {
277→			return g.sessions[i].StartedAt.After(g.sessions[j].StartedAt)
278→		})
279→	}
280→
281→	// Track aggregate totals
282→	var totalSessions int
283→
284→	fmt.Fprintln(w)
285→	printedHeader := false
286→	for _, g := range sortedGroups {
287→		if !printedHeader {
288→			fmt.Fprintln(w, sty.sectionRule("Active Sessions", sty.width))
289→			fmt.Fprintln(w)
290→			printedHeader = true
291→		}
292→
293→		for _, st := range g.sessions {
294→			totalSessions++
295→
296→			agentLabel := string(st.AgentType)
297→			if agentLabel == "" {
298→				agentLabel = unknownPlaceholder
299→			}
300→
301→			shortID := st.SessionID
302→			if len(shortID) > 7 {
303→				shortID = shortID[:7]
304→			}
305→
306→			// Line 1: Agent · shortID
307→			fmt.Fprintf(w, "%s %s %s\n",
308→				sty.render(sty.agent, agentLabel),
309→				sty.render(sty.dim, "·"),
310→				shortID)
311→
312→			// Line 2: > "first prompt" (chevron + quoted, truncated)
313→			if st.FirstPrompt != "" {
314→				prompt := stringutil.TruncateRunes(st.FirstPrompt, 60, "...")
315→				fmt.Fprintf(w, "%s \"%s\"\n", sty.render(sty.dim, ">"), prompt)
316→			}
317→
318→			// Line 3: stats line — started Xd ago · active now · files N · tokens X.Xk
319→			var stats []string
320→			stats = append(stats, "started "+timeAgo(st.StartedAt))
321→
322→			if st.LastInteractionTime != nil && st.LastInteractionTime.Sub(st.StartedAt) > time.Minute {
323→				stats = append(stats, activeTimeDisplay(st.LastInteractionTime))
324→			}
325→
326→			stats = append(stats, "tokens "+formatTokenCount(totalTokens(st.TokenUsage)))
327→
328→			statsLine := strings.Join(stats, sty.render(sty.dim, " · "))
329→			fmt.Fprintln(w, sty.render(sty.dim, statsLine))
330→			fmt.Fprintln(w)
331→		}
332→	}
333→
334→	// Footer: horizontal rule + session count
335→	fmt.Fprintln(w, sty.horizontalRule(sty.width))
336→	var footer string
337→	if totalSessions == 1 {
338→		footer = "1 session"
339→	} else {
340→		footer = fmt.Sprintf("%d sessions", totalSessions)
341→	}
342→	fmt.Fprintln(w, sty.render(sty.dim, footer))
343→	fmt.Fprintln(w)
344→}
