 20→// Transcript message type constants - aliases to transcript package for local use.
 21→const (
 22→	transcriptTypeUser      = transcript.TypeUser
 23→	transcriptTypeAssistant = transcript.TypeAssistant
 24→	contentTypeText         = transcript.ContentTypeText
 25→	contentTypeToolUse      = transcript.ContentTypeToolUse
 26→)
 27→
 28→// PromptResponsePair represents a user prompt and the assistant's responses.
 29→// Used for extracting all interactions from a transcript.
 30→type PromptResponsePair struct {
 31→	Prompt    string
 32→	Responses []string // Multiple responses can occur between tool calls
 33→	Files     []string
 34→}
 35→
 36→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
 37→// Returns pairs in chronological order (oldest first).
 38→// Each pair contains the user's prompt, assistant's text response, and files modified.
 39→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
 40→	var pairs []PromptResponsePair
 41→
 42→	// Find all user prompts (messages with string content, not tool results)
 43→	var userIndices []int
 44→	for i, line := range transcript {
 45→		if line.Type == transcriptTypeUser {
 46→			var msg userMessage
 47→			if err := json.Unmarshal(line.Message, &msg); err != nil {
 48→				continue
 49→			}
 50→			// Only count messages with string content (real user prompts)
 51→			if _, ok := msg.Content.(string); ok {
 52→				userIndices = append(userIndices, i)
 53→			} else if arr, ok := msg.Content.([]interface{}); ok {
 54→				// Check if array has text blocks (also a real user prompt)
 55→				for _, item := range arr {
 56→					if m, ok := item.(map[string]interface{}); ok {
 57→						if m["type"] == contentTypeText {
 58→							userIndices = append(userIndices, i)
 59→							break
 60→						}
 61→					}
 62→				}
 63→			}
 64→		}
 65→	}
 66→
 67→	// For each user prompt, extract the prompt text, following assistant response, and files
 68→	for idx, userIdx := range userIndices {
 69→		// Determine the range for this prompt's conversation
 70→		endIdx := len(transcript)
 71→		if idx < len(userIndices)-1 {
 72→			endIdx = userIndices[idx+1]
 73→		}
 74→
 75→		// Extract prompt text
 76→		prompt := extractUserPromptAt(transcript, userIdx)
 77→		if prompt == "" {
 78→			continue
 79→		}
 80→
 81→		// Extract assistant responses and files from this range
 82→		slice := transcript[userIdx:endIdx]
 83→		responses := extractAssistantResponses(slice)
 84→		files := extractModifiedFiles(slice)
 85→
 86→		pairs = append(pairs, PromptResponsePair{
 87→			Prompt:    prompt,
 88→			Responses: responses,
 89→			Files:     files,
 90→		})
 91→	}
 92→
 93→	return pairs
 94→}
 95→
 96→// extractUserPromptAt extracts the user prompt at the given index.
 97→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
 98→func extractUserPromptAt(lines []transcriptLine, idx int) string {
 99→	if idx >= len(lines) || lines[idx].Type != transcriptTypeUser {
100→		return ""
101→	}
102→
103→	return transcript.ExtractUserContent(lines[idx].Message)
104→}
105→
106→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
107→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
108→func extractAssistantResponses(transcript []transcriptLine) []string {
109→	var texts []string
110→	for _, line := range transcript {
111→		if line.Type == transcriptTypeAssistant {
112→			var msg assistantMessage
113→			if err := json.Unmarshal(line.Message, &msg); err != nil {
114→				continue
115→			}
116→
117→			for _, block := range msg.Content {
118→				if block.Type == contentTypeText && block.Text != "" {
119→					texts = append(texts, block.Text)
120→				}
121→			}
122→		}
123→	}
124→	return texts
125→}
126→
127→// extractUserPrompts extracts all user messages from the transcript in order.
128→// Only considers messages with string content (not tool results).
129→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
130→func extractUserPrompts(transcript []transcriptLine) []string {
131→	var prompts []string
132→	for i := range transcript {
133→		if transcript[i].Type != transcriptTypeUser {
134→			continue
135→		}
136→		var msg userMessage
137→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
138→			continue
139→		}
140→
141→		// Handle string content
142→		if str, ok := msg.Content.(string); ok {
143→			prompts = append(prompts, textutil.StripIDEContextTags(str))
144→			continue
145→		}
146→
147→		// Handle array content (only if it contains text blocks)
148→		if arr, ok := msg.Content.([]interface{}); ok {
149→			var texts []string
150→			for _, item := range arr {
151→				if m, ok := item.(map[string]interface{}); ok {
152→					if m["type"] == contentTypeText {
153→						if text, ok := m["text"].(string); ok {
154→							texts = append(texts, text)
155→						}
156→					}
157→				}
158→			}
159→			if len(texts) > 0 {
160→				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
161→			}
162→		}
163→	}
164→	return prompts
165→}
