167→// extractLastUserPrompt extracts the last user message from the transcript.
168→// Only considers messages with string content (not tool results).
169→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
170→func extractLastUserPrompt(transcript []transcriptLine) string {
171→	prompts := extractUserPrompts(transcript)
172→	if len(prompts) == 0 {
173→		return ""
174→	}
175→	return prompts[len(prompts)-1]
176→}
