178→// findLastUserUUID finds the UUID of the last user message (that has string content)
179→func findLastUserUUID(transcript []transcriptLine) string {
180→	for i := len(transcript) - 1; i >= 0; i-- {
181→		if transcript[i].Type == transcriptTypeUser {
182→			var msg userMessage
183→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
184→				continue
185→			}
186→			// Only count messages with string content (not tool results)
187→			if _, ok := msg.Content.(string); ok {
188→				return transcript[i].UUID
189→			}
190→		}
191→	}
192→	return ""
193→}
194→
195→// filterTranscriptAfterUUID returns transcript lines after the given UUID
196→func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
197→	if uuid == "" {
198→		return transcript
199→	}
200→
201→	foundIndex := -1
202→	for i, line := range transcript {
203→		if line.UUID == uuid {
204→			foundIndex = i
205→			break
206→		}
207→	}
208→
209→	if foundIndex == -1 || foundIndex == len(transcript)-1 {
210→		return transcript
211→	}
212→
213→	return transcript[foundIndex+1:]
214→}
