216→// extractModifiedFiles extracts the list of files modified by tool calls
217→func extractModifiedFiles(transcript []transcriptLine) []string {
218→	fileSet := make(map[string]bool)
219→	var files []string
220→
221→	for _, line := range transcript {
222→		if line.Type == transcriptTypeAssistant {
223→			var msg assistantMessage
224→			if err := json.Unmarshal(line.Message, &msg); err != nil {
225→				continue
226→			}
227→
228→			for _, block := range msg.Content {
229→				if block.Type == contentTypeToolUse {
230→					isModifyTool := false
231→					for _, name := range claudecode.FileModificationTools {
232→						if block.Name == name {
233→							isModifyTool = true
234→							break
235→						}
236→					}
237→
238→					if isModifyTool {
239→						var input toolInput
240→						if err := json.Unmarshal(block.Input, &input); err != nil {
241→							continue
242→						}
243→
244→						file := input.FilePath
245→						if file == "" {
246→							file = input.NotebookPath
247→						}
248→
249→						if file != "" && !fileSet[file] {
250→							fileSet[file] = true
251→							files = append(files, file)
252→						}
253→					}
254→				}
255→			}
256→		}
257→	}
258→
259→	return files
260→}
