295→// FindCheckpointUUID finds the UUID of the message containing the tool_result
296→// for the given tool_use_id. This is used to find the checkpoint point for
297→// transcript truncation when rewinding to a task.
298→// Returns the UUID and true if found, empty string and false otherwise.
299→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
300→	for _, line := range transcript {
301→		if line.Type != transcriptTypeUser {
302→			continue
303→		}
304→
305→		var msg userMessageWithToolResults
306→		if err := json.Unmarshal(line.Message, &msg); err != nil {
307→			continue
308→		}
309→
310→		for _, block := range msg.Content {
311→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
312→				return line.UUID, true
313→			}
314→		}
315→	}
316→	return "", false
317→}
318→
319→// TruncateTranscriptAtUUID returns transcript lines up to and including the
320→// line with the given UUID. If the UUID is not found or is empty, returns
321→// the entire transcript.
322→//
323→//nolint:revive // Exported for testing purposes
324→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
325→	if uuid == "" {
326→		return transcript
327→	}
328→
329→	for i, line := range transcript {
330→		if line.UUID == uuid {
331→			return transcript[:i+1]
332→		}
333→	}
334→
335→	// UUID not found, return full transcript
336→	return transcript
337→}
