339→// writeTranscript writes transcript lines to a file in JSONL format.
340→func writeTranscript(path string, transcript []transcriptLine) error {
341→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
342→	if err != nil {
343→		return fmt.Errorf("failed to create file: %w", err)
344→	}
345→	defer func() { _ = file.Close() }()
346→
347→	for _, line := range transcript {
348→		data, err := json.Marshal(line)
349→		if err != nil {
350→			return fmt.Errorf("failed to marshal line: %w", err)
351→		}
352→		if _, err := file.Write(data); err != nil {
353→			return fmt.Errorf("failed to write line: %w", err)
354→		}
355→		if _, err := file.WriteString("\n"); err != nil {
356→			return fmt.Errorf("failed to write newline: %w", err)
357→		}
358→	}
359→
360→	return nil
361→}
