249→// filterToUncommittedFiles removes files from the list that are already committed to HEAD
250→// with matching content. This prevents re-adding files that an agent committed mid-turn
251→// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
252→// HEAD or with different content in the working tree are kept. Fails open: if any git
253→// operation errors, returns the original list unchanged.
254→func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
255→	if len(files) == 0 {
256→		return files
257→	}
258→
259→	repo, err := openRepository(ctx)
260→	if err != nil {
261→		return files // fail open
262→	}
263→
264→	head, err := repo.Head()
265→	if err != nil {
266→		return files // fail open (empty repo, detached HEAD, etc.)
267→	}
268→
269→	commit, err := repo.CommitObject(head.Hash())
270→	if err != nil {
271→		return files // fail open
272→	}
273→
274→	headTree, err := commit.Tree()
275→	if err != nil {
276→		return files // fail open
277→	}
278→
279→	var result []string
280→	for _, relPath := range files {
281→		headFile, err := headTree.File(relPath)
282→		if err != nil {
283→			// File not in HEAD — it's uncommitted
284→			result = append(result, relPath)
285→			continue
286→		}
287→
288→		// File is in HEAD — compare content with working tree
289→		absPath := filepath.Join(repoRoot, relPath)
290→		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
291→		if err != nil {
292→			// Can't read working tree file (deleted?) — keep it
293→			result = append(result, relPath)
294→			continue
295→		}
296→
297→		headContent, err := headFile.Contents()
298→		if err != nil {
299→			result = append(result, relPath)
300→			continue
301→		}
302→
303→		if string(workingContent) != headContent {
304→			// Working tree differs from HEAD — uncommitted changes
305→			result = append(result, relPath)
306→		}
307→		// else: content matches HEAD — already committed, skip
308→	}
309→
310→	return result
311→}
