477→// preTaskFilePrefix is the prefix for pre-task state files
478→const preTaskFilePrefix = "pre-task-"
479→
480→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
481→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
482→// When multiple pre-task files exist (nested subagents), returns the most recently
483→// modified one.
484→// Works correctly from any subdirectory within the repository.
485→func FindActivePreTaskFile() (taskToolUseID string, found bool) {
486→	tmpDirAbs, err := paths.AbsPath(context.TODO(), paths.EntireTmpDir)
487→	if err != nil {
488→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
489→	}
490→	entries, err := os.ReadDir(tmpDirAbs)
491→	if err != nil {
492→		return "", false
493→	}
494→
495→	var latestFile string
496→	var latestTime time.Time
497→
498→	for _, entry := range entries {
499→		if entry.IsDir() {
500→			continue
501→		}
502→		name := entry.Name()
503→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
504→			continue
505→		}
506→
507→		// Check modification time for nested subagent handling
508→		info, err := entry.Info()
509→		if err != nil {
510→			continue
511→		}
